DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['financeiro_acessos','financeiro_config','financeiro_cadastros','financeiro_catalogo','financeiro_cobrancas','financeiro_itens','financeiro_pagamentos','financeiro_alocacoes','financeiro_abatimentos','financeiro_contatos','financeiro_caixa','financeiro_auditoria','financeiro_operacoes'] LOOP EXECUTE format('REVOKE ALL ON TABLE public.%I FROM anon, authenticated',t);EXECUTE format('GRANT ALL ON TABLE public.%I TO service_role',t);IF t<>'financeiro_operacoes' THEN EXECUTE format('GRANT SELECT ON TABLE public.%I TO authenticated',t);END IF;END LOOP;END $$;